package com.bank.connpool.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class SlowTxService {

    /**
     * Connection held: 3010ms (10ms DB + 3000ms network).
     * 10 connections, 3s each = max 3.3 req/s!
     * At 10 req/s → pool exhausted in 3 seconds.
     */
    @Transactional
    public void processWithSlowCall() {
        log.warn("[SLOW TX] Connection acquired — doing DB work (10ms)...");
        // DB work: 10ms

        log.warn("[SLOW TX] Now calling external API inside TX (3000ms)...");
        try { Thread.sleep(3000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        // Connection WASTED for 3 seconds of non-DB work!

        log.warn("[SLOW TX] Done. Connection held 3010ms total. Only 10ms was DB work.");
    }
}
