package com.bank.connpool.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class FastTxService {

    /**
     * Connection held: 10ms (DB only — no network).
     * 10 connections, 10ms each = max 1000 req/s!
     * 300× improvement over SlowTxService.
     */
    @Transactional
    public void processDbOnly() {
        log.info("[FAST TX] Connection acquired — DB work only (10ms)...");
        // DB work: 10ms. Connection released immediately after commit.
    }

    // Network call OUTSIDE any @Transactional method — no connection held
    public void callExternalApi() {
        log.info("[NO TX] Calling external API (3000ms) — NO connection held...");
        try { Thread.sleep(3000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
