package com.bank.connpool.monitor;

import com.zaxxer.hikari.HikariDataSource;
import com.zaxxer.hikari.HikariPoolMXBean;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import javax.sql.DataSource;

@Component
@RequiredArgsConstructor
@Slf4j
@EnableScheduling
public class PoolMetricsLogger {

    private final DataSource dataSource;

    @Scheduled(fixedRate = 2000)
    public void logPool() {
        if (dataSource instanceof HikariDataSource h) {
            HikariPoolMXBean p = h.getHikariPoolMXBean();
            log.info("[POOL] active={}, idle={}, waiting={}, total={}",
                p.getActiveConnections(), p.getIdleConnections(),
                p.getThreadsAwaitingConnection(), p.getTotalConnections());

            if (p.getThreadsAwaitingConnection() > 0) {
                log.warn("[POOL] {} threads WAITING for connection! " +
                    "Latency = wait time, not SQL time!", p.getThreadsAwaitingConnection());
            }
        }
    }
}
